const root = document.getElementById('app');
const SESSION_KEY = 'slay_investments_session';
const SESSION_USER_KEY = 'slay_investments_session_user';
const RESULT_KEY = 'slay_investments_result';
const LEVEL_KEY = userId => `slay_investments_level_${userId}`;
const MONTHS = ['январь','февраль','март','апрель','май','июнь','июль','август','сентябрь','октябрь','ноябрь','декабрь'];
const MONTHS_IN = ['январе','феврале','марте','апреле','мае','июне','июле','августе','сентябре','октябре','ноябре','декабре'];
const MONTHS_GENITIVE = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
let user = null;
let session = null;
let activeResult = null;
let level = 'easy';
let profileMenuOutsideHandler = null;

const icons = { arrow:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>', mark:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 17.5 9 12l3.4 3.4L20 7"/></svg>' };
const levelMeta = { easy:{name:'Easy',desc:'Основы анализа',note:'Понятные статьи и подсказки'}, medium:{name:'Medium',desc:'Конкурирующие гипотезы',note:'Больше факторов, меньше подсказок'}, hard:{name:'Hard',desc:'Неоднозначные сигналы',note:'Глубокий разбор аргументации'} };
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(v){return `${new Intl.NumberFormat('ru-RU').format(v)} ₽`;}
function pct(v){return `${v>0?'+':''}${Number(v).toLocaleString('ru-RU',{maximumFractionDigits:2})}%`;}
function pluralTimes(value){const n=Math.abs(Number(value))%100,last=n%10;return last===1&&n!==11?'раз':last>=2&&last<=4&&(n<12||n>14)?'раза':'раз';}
class ApiError extends Error{constructor(message,status=0,code=''){super(message);this.status=status;this.code=code;}}
async function api(url, options={}){let response;try{response=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});}catch{throw new ApiError('Не удалось связаться с сервером. Проверьте подключение и повторите попытку.');}const data=await response.json().catch(()=>({}));if(!response.ok){let message=data.error||'Не удалось выполнить запрос.';if(data.code==='EMAIL_EXISTS')message='Аккаунт с таким email уже существует. Войдите или укажите другой адрес.';else if(response.status>=500)message='Сервис временно недоступен. Ваши данные в форме сохранены — попробуйте ещё раз позже.';throw new ApiError(message,response.status,data.code||'');}return data;}
function brand(){return `<a class="brand" href="/" id="brand-home" aria-label="Slay Investments — на главную"><span class="brand-icon" aria-hidden="true">SI</span><span>Slay <b>Investments</b></span></a>`;}
const catIcon='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M6 12 5 4l8 5a12 12 0 0 1 6 0l8-5-1 8a11 11 0 1 1-20 0Z"/><path d="M12 16h.1M20 16h.1M13 21q3 2 6 0"/></svg>';
function shell(content){return `<div class="shell"><header class="topbar">${brand()}<nav class="nav-right">${user?`<div class="profile-menu"><button class="profile-menu-trigger" id="profile-menu-trigger" type="button" aria-label="Меню профиля" aria-haspopup="menu" aria-expanded="false">${catIcon}</button><div class="profile-menu-popover" id="profile-menu" role="menu" hidden><button type="button" role="menuitem" id="nav-profile">Мой профиль</button><button type="button" role="menuitem" id="nav-logout">Выйти</button></div></div>`:''}</nav></header>${content}</div>`;}
function bindNav(){const gameTop=root.querySelector('.game-top');if(user&&gameTop&&!gameTop.querySelector('.profile-menu'))gameTop.insertAdjacentHTML('beforeend',`<div class="profile-menu"><button class="profile-menu-trigger" id="profile-menu-trigger" type="button" aria-label="Меню профиля" aria-haspopup="menu" aria-expanded="false">${catIcon}</button><div class="profile-menu-popover" id="profile-menu" role="menu" hidden><button type="button" role="menuitem" id="nav-profile">Мой профиль</button><button type="button" role="menuitem" id="nav-logout">Выйти</button></div></div>`);document.getElementById('brand-home')?.addEventListener('click',e=>{e.preventDefault();user?dashboard():landing();});const trigger=document.getElementById('profile-menu-trigger'),menu=document.getElementById('profile-menu');const closeMenu=()=>{if(menu&&!menu.hidden){menu.hidden=true;trigger?.setAttribute('aria-expanded','false');}};trigger?.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;trigger.setAttribute('aria-expanded',String(open));if(open)menu.querySelector('button')?.focus();});menu?.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();trigger?.focus();}});if(profileMenuOutsideHandler)document.removeEventListener('pointerdown',profileMenuOutsideHandler);profileMenuOutsideHandler=e=>{if(menu&&!menu.contains(e.target)&&!trigger?.contains(e.target))closeMenu();};document.addEventListener('pointerdown',profileMenuOutsideHandler);document.getElementById('nav-profile')?.addEventListener('click',profileView);document.getElementById('nav-logout')?.addEventListener('click',async()=>{await api('/api/auth/logout',{method:'POST'}).catch(()=>{});user=null;session=null;localStorage.removeItem(SESSION_KEY);localStorage.removeItem(RESULT_KEY);landing();});}
function landing(){root.innerHTML=shell(`<main class="landing"><section class="hero-grid"><div class="hero"><h1>Slay Investments – инвестиции, в которые хочется вложиться</h1><p class="hero-copy">Дадим возможность понять и научиться, чем занимаются умные дядьки в костюмах из Instagram (запрещен в РФ). Вы знаете, что такое MOEX? Вот и мы не знали, а он здесь есть. Это и даже больше.</p><div class="hero-actions"><button class="primary" id="hero-cta">${user?'Открыть рабочий стол':'Создать личный кабинет'} ${icons.arrow}</button></div></div><aside class="hero-ledger market-preview"><div id="preview-chart" class="chart-wrap preview-chart" role="img" aria-label="Декоративный случайный график"></div></aside></section></main><footer class="disclaimer"><span>ОООбман</span><span>2026-2026</span><span>Slay Spirits Inc.</span><span>Все заговор и рофл, разработчики не несут ответственности ни за что, даже за себя</span></footer>`);bindNav();loadPreview();document.getElementById('hero-cta').onclick=()=>user?dashboard():authView('register');}
function loadPreview(){const chart=document.getElementById('preview-chart');if(!chart)return;let value=100;const points=Array.from({length:60},(_,index)=>{value+=Math.random()*8-3.8;return{value,date:index+1};});chart.innerHTML=chartSvg(points,{mode:'preview'});}
function authView(mode='register',message=''){root.innerHTML=shell(`<main class="auth-layout"><section class="auth-copy"><h1>${mode==='register'?'Slay-стойка регистрации':'Вход в Slay'}</h1>${mode==='register'?'<p class="auth-subtitle">из персонала только животные (разработчики)</p>':''}</section><form class="panel auth-form" id="auth-form"><div class="form-kicker">${mode==='register'?'Регистрация':'Вход'}</div><div class="error auth-error" id="auth-error" role="alert" aria-live="polite" hidden></div>${mode==='register'?`<label class="field-label">Имя или никнейм<input class="field" name="display_name" minlength="2" maxlength="40" required></label>`:''}<label class="field-label">Email<input class="field" name="email" type="email" autocomplete="email" required></label><label class="field-label">Пароль<input class="field" name="password" type="password" minlength="8" autocomplete="${mode==='register'?'new-password':'current-password'}" required></label>${mode==='register'?`<p class="form-hint">Не менее 8 символов, с буквами и цифрами.</p>`:''}<button class="primary" type="submit">${mode==='register'?'Создать аккаунт':'Войти'} ${icons.arrow}</button><button class="text-button" type="button" id="switch-auth">${mode==='register'?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться'}</button></form></main>`);bindNav();document.getElementById('switch-auth').onclick=()=>authView(mode==='register'?'login':'register');document.getElementById('auth-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type="submit"]'),box=document.getElementById('auth-error');button.disabled=true;button.textContent='Отправляем…';const body=Object.fromEntries(new FormData(form));try{const data=await api(`/api/auth/${mode}`,{method:'POST',body:JSON.stringify(body)});user=data.user;mode==='register'?tutorialView():dashboard();}catch(err){box.textContent=err.message;box.hidden=false;const message=err.message.toLowerCase();const field=message.includes('email')?form.elements.email:message.includes('парол')?form.elements.password:message.includes('имя')?form.elements.display_name:null;if(field){field.setAttribute('aria-invalid','true');field.focus();}button.disabled=false;button.textContent=mode==='register'?'Создать аккаунт':'Войти';}};}
const tutorialSteps=[{eyebrow:'01 · Акция',title:'Цена — это ожидание рынка',body:'Акция — доля в компании. Её цена меняется, когда участники пересматривают ожидания о будущих доходах и рисках.',action:'Отметьте: цена акции может меняться даже до публикации отчёта.',kind:'check'},{eyebrow:'02 · График',title:'Сначала смотрите на форму',body:'График показывает последовательность закрытий. Он описывает прошлое и помогает задать вопросы, но не раскрывает будущее.',action:'Выберите, что показывает график.',kind:'choice'},{eyebrow:'03 · Риск',title:'Обоснованное решение не гарантирует результат',body:'Риск — диапазон возможных исходов. Даже сильная гипотеза может столкнуться с новым событием, которого не было в данных.',action:'Согласны с утверждением?',kind:'choice'},{eyebrow:'04 · Практика',title:'Сделайте пробный раунд',body:'В каждом раунде вы изучаете 60 дней, выбираете компанию и период, прогнозируете следующие 30 дней, отмечаете факторы и стратегию.',action:'Я готов(а) к Easy.',kind:'finish'}];
function tutorialView(){let step=Math.min(Number(user?.tutorial_step||0),3);if(step===3){tutorialPracticeView();return;}const s=tutorialSteps[step];root.innerHTML=shell(`<main class="tutorial-layout"><div class="tutorial-head"><div class="eyebrow">Обязательный вводный урок · ${String(step+1).padStart(2,'0')} / 04</div><div class="tutorial-progress">${tutorialSteps.map((_,i)=>`<span class="${i<=step?'active':''}"></span>`).join('')}</div></div><section class="tutorial-grid"><article class="tutorial-card"><div class="tutorial-step-index">${String(step+1).padStart(2,'0')}</div><div class="eyebrow">${s.eyebrow}</div><h1>${s.title}</h1><p>${s.body}</p><div class="tutorial-visual">${step===0?'<div class="price-ticker"><span>ОЖИДАНИЯ</span><strong>+ / −</strong><small>Цена меняется, когда меняется взгляд на будущее.</small></div>':step===1?'<div class="tutorial-chart chart-wrap" id="tutorial-chart" role="img" aria-label="Historical chart for 60 trading days"></div>':step===2?'<div class="risk-scale"><span>неопределённость</span><b>±</b><span>исходы</span></div>':'<div class="practice-list"><span>01 / Контекст</span><span>02 / Гипотеза</span><span>03 / Разбор</span></div>'}</div></article><form class="panel tutorial-form" id="tutorial-form"><div class="section-label">Ваше действие</div><p class="tutorial-prompt">${s.action}</p>${step===0?`<label class="choice-line"><input type="checkbox" name="ok" required><span>Да, цена отражает ожидания и риск.</span></label>`:step===1?`<label class="choice-line"><input type="radio" name="answer" value="yes" required><span>Прошлые торговые закрытия</span></label><label class="choice-line"><input type="radio" name="answer" value="no"><span>Гарантированное направление завтра</span></label>`:step===2?`<label class="choice-line"><input type="radio" name="answer" value="yes" required><span>Да, будущая информация может изменить исход.</span></label><label class="choice-line"><input type="radio" name="answer" value="no"><span>Нет, хороший анализ всегда гарантирует прибыль.</span></label>`:'<div class="success-note">После завершения откроется уровень Easy. Туториал можно повторить из профиля.</div>'}<button class="primary" type="submit">${step===3?'Завершить туториал':'Продолжить'} ${icons.arrow}</button><div class="form-hint">Прогресс сохраняется после каждого шага.</div></form></section></main>`);bindNav();if(step===1)loadTutorialChart();document.getElementById('tutorial-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget);if(step===1&&data.get('answer')!=='yes'||step===2&&data.get('answer')!=='yes'){e.currentTarget.insertAdjacentHTML('beforeend','<div class="error">Выберите вариант, который соответствует объяснению.</div>');return;}try{const done=step===3;const result=await api('/api/tutorial/progress',{method:'POST',body:JSON.stringify({step:step+1,completed:done})});user=result.user;done?dashboard():tutorialView();}catch(err){e.currentTarget.insertAdjacentHTML('beforeend',`<div class="error">${esc(err.message)}</div>`);}};}
function levelCards(){const levels=user?.levels||{easy:true,medium:false,hard:false},copy={easy:{desc:'Основы анализа'},medium:{desc:'Потеряйся в трёх соснах',note:'Больше воды, меньше смысла'},hard:{desc:'Кто куда?',note:'Воды с океан, смысла с горошинку. Удачи'}};return `<section class="level-grid" aria-label="Уровни сложности">${Object.entries(levelMeta).map(([key,m],i)=>{const open=Boolean(levels[key]),title=copy[key];return `<button type="button" class="level-card ${open?'open':'locked'} ${level===key?'selected':''}" data-level="${key}" ${open?'':'disabled'} aria-label="Уровень ${m.name}: ${title.desc}${open?'. Начать уровень.':'. Закрыт. Завершите предыдущую полную сессию.'}"><span>${open?'ДОСТУПЕН':'ЗАКРЫТ'} · ${String(i+1).padStart(2,'0')}</span><b>${m.name}</b><strong>${title.desc}</strong><small>${open?(title.note||m.note):'Завершите предыдущую пятираундовую сессию'}</small></button>`}).join('')}</section>`;}
async function dashboard(){if(!user)return landing();if(!user.tutorial_completed)return tutorialView();if(!user.levels?.[level]){const savedLevel=localStorage.getItem(LEVEL_KEY(user.id));level=savedLevel&&user.levels?.[savedLevel]?savedLevel:"easy";}const canResume=localStorage.getItem(SESSION_USER_KEY)===user.id&&Boolean(localStorage.getItem(SESSION_KEY));root.innerHTML=shell(`<main class="dashboard"><section class="dashboard-head"><div><h1>Главная панель</h1></div></section>${levelCards()}<section class="panel dashboard-panel"><h2>Пять раундов, шесть жизней и одно большое желание учиться</h2><p>Изучайте реальные исторические данные, принимайте решения и после каждого раунда разбирайте, что повлияло на результат.</p>${canResume?`<button class="primary" id="continue-session">Продолжить незавершённую сессию ${icons.arrow}</button>`:''}</section></main>`);bindNav();document.querySelectorAll('.level-card.open').forEach(el=>el.addEventListener('click',()=>{level=el.dataset.level;localStorage.setItem(LEVEL_KEY(user.id),level);startGame(false);}));document.getElementById('continue-session')?.addEventListener('click',()=>startGame(true));}
async function startGame(resume=false){activeResult=null;session=null;root.innerHTML='<div class="loading">Открываем исследовательскую сессию…</div>';try{const saved=resume&&localStorage.getItem(SESSION_USER_KEY)===user?.id?localStorage.getItem(SESSION_KEY):null;if(saved){try{session=await api('/api/session',{headers:{'X-Session-Id':saved}});}catch{clearSavedSession();session=null;}}if(session?.round_index>=5){clearSavedSession();session=null;dashboard();return;}if(!session){session=await api('/api/session',{method:'POST',body:JSON.stringify({level})});localStorage.setItem(SESSION_KEY,session.session_id);localStorage.setItem(SESSION_USER_KEY,user.id);localStorage.removeItem(RESULT_KEY);}const previous=JSON.parse(localStorage.getItem(RESULT_KEY)||'null');if(previous&&previous.session_id===session.session_id&&previous.index===session.round_index-1)activeResult=previous.result;render();}catch(err){errorScreen(err.message);}}
function clearSavedSession(){localStorage.removeItem(SESSION_KEY);localStorage.removeItem(SESSION_USER_KEY);localStorage.removeItem(RESULT_KEY);}
function progress(){return `<div class="round-track">${[0,1,2,3,4].map(i=>`<span class="track-dot ${i<session.round_index?'done':i===session.round_index?'active':''}">${i<session.round_index?'✓':i+1}</span>`).join('')}</div>`;}
function hintCard(hint,index){return `<article class="hint-card"><div><span>Подсказка ${index+1} · ${esc(hint.kind)}</span><small>${esc(hint.label)}</small></div><p>${esc(hint.text)}</p></article>`;}
function sourceItem(value){const label=String(value||''),match=label.match(/https?:\/\/[^\s]+/);if(!match)return `<li>${esc(label)}</li>`;const href=match[0].replace(/[),.;]+$/,'');return `<li>${esc(label.replace(match[0],'').replace(/[\s—–-]+$/,''))} · <a href="${esc(href)}" target="_blank" rel="noreferrer">Открыть источник ↗</a></li>`;}
function chartSvg(points,options={}){
  if(typeof options==='boolean')options={mode:options?'revealed':'round'};
  const mode=options.mode||'round',shown=mode==='revealed'?points.slice(0,90):points.slice(0,60);
  const vals=shown.map(p=>Number(p.value??p.close));
  if(!vals.length)return '<div class="chart-empty">График недоступен</div>';
  const min=Math.min(...vals),max=Math.max(...vals),spread=Math.max(1,max-min);
  const w=760,h=300,left=mode==='preview'?14:54,right=14,top=18,bottom=mode==='preview'?14:42,pw=w-left-right,ph=h-top-bottom;
  const forecast=options.forecast||null,base=Number(vals[Math.min(59,vals.length-1)]);
  const forecastDelta=spread*.24;
  const futureVals=forecast?Array.from({length:31},(_,i)=>base+(forecast==='up'?1:forecast==='down'?-1:0)*forecastDelta*i/30):[];
  const yVals=vals.concat(futureVals),yMin=Math.min(...yVals)-spread*.14,yMax=Math.max(...yVals)+spread*.14;
  const x=i=>left+i/(mode==='preview'?Math.max(shown.length-1,1):89)*pw,y=v=>top+(1-(v-yMin)/(yMax-yMin))*ph;
  const coords=shown.map((p,i)=>[x(i),y(Number(p.value??p.close))]);
  const path=coords.map(([cx,cy],i)=>`${i?'L':'M'}${cx.toFixed(2)} ${cy.toFixed(2)}`).join(' ');
  const guides=mode==='preview'?'':[0,.33,.66,1].map(t=>{const gy=top+t*ph,label=(yMax-(yMax-yMin)*t).toFixed(1);return `<line class="chart-axis" x1="${left}" y1="${gy}" x2="${w-right}" y2="${gy}"/><text class="axis-label axis-y" x="${left-8}" y="${gy+4}" text-anchor="end">${label}</text>`;}).join('');
  const x30=x(29.5),x60=x(59.5),x90=x(89),futureStart=mode==='revealed'?shown.length:60;
  const bands=`<rect class="chart-band history-one" x="${left}" y="${top}" width="${x30-left}" height="${ph}"/><rect class="chart-band history-two" x="${x30}" y="${top}" width="${x60-x30}" height="${ph}"/><rect class="chart-band forecast-band" x="${x60}" y="${top}" width="${x90-x60}" height="${ph}"/>`;
  const markers=mode==='preview'?'':`<line class="chart-split" x1="${x30}" y1="${top}" x2="${x30}" y2="${top+ph}"/><line class="chart-split" x1="${x60}" y1="${top}" x2="${x60}" y2="${top+ph}"/><line class="decision-mark" x1="${x60}" y1="${top}" x2="${x60}" y2="${top+ph}"/>`;
  const xLabels=mode==='preview'?'':`<text class="axis-label" x="${left}" y="${h-8}">День 1</text><text class="axis-label" x="${x30}" y="${h-8}" text-anchor="middle">30</text><text class="axis-label" x="${x60}" y="${h-8}" text-anchor="middle">60</text><text class="axis-label" x="${x90}" y="${h-8}" text-anchor="end">90</text><text class="segment-label" x="${(left+x30)/2}" y="${top+13}" text-anchor="middle">Период I</text><text class="segment-label" x="${(x30+x60)/2}" y="${top+13}" text-anchor="middle">Период II</text><text class="segment-label future" x="${(x60+x90)/2}" y="${top+13}" text-anchor="middle">${mode==='revealed'?'Факт':'Прогнозируемый период'}</text>`;
  const area=mode==='preview'?`<path class="chart-area" d="${path} L ${coords.at(-1)[0]} ${top+ph} L ${coords[0][0]} ${top+ph} Z"/>`:'';
  const pointMarks=mode==='preview'?'':shown.map((p,i)=>{const [cx,cy]=coords[i],day=i+1,title=p.date?`${p.date} · ${Number(p.close).toLocaleString('ru-RU')}`:`Торговый день ${day} · ${Number(p.value??p.close).toLocaleString('ru-RU',{maximumFractionDigits:2})}`;return `<circle class="chart-hit" cx="${cx}" cy="${cy}" r="5"><title>${esc(title)}</title></circle>`;}).join('');
  let forecastPath='';
  if(forecast&&mode!=='preview'){
    const startIndex=Math.min(59,shown.length-1),start=Number(shown[startIndex].value??shown[startIndex].close),line=Array.from({length:31},(_,i)=>`${i?'L':'M'}${x(startIndex+i).toFixed(2)} ${y(start+(forecast==='up'?1:forecast==='down'?-1:0)*forecastDelta*i/30).toFixed(2)}`).join(' ');
    forecastPath=`<path class="forecast-line" d="${line}"/><text class="forecast-label" x="${x(89)-4}" y="${y(start+(forecast==='up'?forecastDelta:forecast==='down'?-forecastDelta:0))-8}" text-anchor="end">Ваш прогноз</text>`;
  }
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="${mode==='preview'?'Декоративный график':'Исторический график: Период I, Период II и прогнозируемый период'}"><defs><linearGradient id="chartGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#b88b62" stop-opacity=".24"/><stop offset="1" stop-color="#b88b62" stop-opacity="0"/></linearGradient></defs>${mode==='preview'?'':bands}${guides}${area}<path class="chart-line ${mode==='revealed'?'revealed':''}" d="${path}"/>${pointMarks}${forecastPath}${markers}${xLabels}</svg>`;
}
function roundView(){
  const r=session.current,companies=r.companies.map(c=>`<option value="${c.ticker}">${esc(c.name)} · ${esc(c.sector)}</option>`).join('');
  const factors=r.factors.map((f,i)=>`<label class="factor"><input type="checkbox" name="factor" value="${i}"><span><b>${esc(f.name)}</b><small>${esc(f.description)}</small></span></label>`).join('');
  const quiz=r.quiz.map((q,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${esc(q.question)}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="quiz-${q.id}" value="${j}"><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('');
  const b=r.briefing||{},years=[...new Set((r.periods||[]).map(p=>p[0]))].sort(),hintState=session.hint_state||{used:0,remaining:r.hint_limit||6,opened:[]};
  const yearOptions=years.map(y=>`<option value="${y}">${y}</option>`).join('');
  root.innerHTML=`<div class="game-shell"><header class="game-top"><div class="game-title">${brand()}</div><div class="game-progress">${progress()}<span class="game-meta">${levelMeta[session.level||level].name} · Раунд ${session.round_index+1} из 5</span></div><div class="profile-menu"><button class="profile-menu-trigger" id="profile-menu-trigger" type="button" aria-label="Меню профиля" aria-haspopup="menu" aria-expanded="false">${catIcon}</button><div class="profile-menu-popover" id="profile-menu" role="menu" hidden><button type="button" role="menuitem" id="nav-profile">Мой профиль</button><button type="button" role="menuitem" id="nav-logout">Выйти</button></div></div></header><main>
    <div class="game-tabs" role="tablist" aria-label="Области раунда"><button type="button" class="tab-button active" data-panel="investigation" role="tab" aria-selected="true">Исследование</button><button type="button" class="tab-button" data-panel="decision" role="tab" aria-selected="false">Решение</button></div>
    <div class="game-grid"><section class="panel chart-panel game-area" id="investigation" data-area="investigation" role="tabpanel">
      <article class="briefing"><p class="investigation-lead">${esc(r.intro)}</p><div class="article-extra" aria-label="Дополнительный исторический контекст">${(r.article||[]).map(paragraph=>`<p>${esc(paragraph)}</p>`).join('')}</div><div class="briefing-row"><span>Рыночный контекст</span><p>${esc(b.context||'Сопоставьте новость с условиями отрасли и рынка.')}</p></div><div class="briefing-row"><span>Что неизвестно</span><p>${esc(b.circumstances||'Несколько факторов могли действовать одновременно.')}</p></div><div class="briefing-row"><span>Что важно проверить</span><p>${esc(b.consequences||'Сопоставьте несколько объяснений движения цены.')}</p></div></article>
      <div class="panel-head"><div><h2>Историческая цена</h2><div class="panel-sub">День решения отмечен пунктиром</div></div><button type="button" class="help-button" id="chart-help" aria-expanded="false">Как читать график</button></div><div class="chart-toolbar" aria-label="Масштаб графика"><button type="button" id="chart-zoom-out" aria-label="Уменьшить график">−</button><button type="button" id="chart-zoom-in" aria-label="Увеличить график">+</button><button type="button" id="chart-zoom-reset">Сбросить масштаб</button><span>Перемещайтесь по увеличенному графику прокруткой</span></div><div class="chart-wrap chart-viewport" id="round-chart" tabindex="0">${chartSvg(r.chart)}</div><div class="chart-tooltip" id="chart-tooltip" role="status" aria-live="polite" hidden></div><div class="chart-legend"><span><i class="legend-line actual"></i>Исторические данные</span><span><i class="legend-line predicted"></i>Схема вашего прогноза</span></div><div class="chart-footnote"><span>Дни 1–30 · Период I</span><span>31–60 · Период II</span><span>61–90 · продолжение откроется после ответа</span></div><p class="chart-help-copy" id="chart-help-copy" hidden>Цена в начале графика принята за 100. Значение 110 означает рост на 10% относительно первого наблюдения. Наведите на область графика или коснитесь её, чтобы увидеть день и изменение; точные даты откроются после фиксации решения.</p>
      <section class="hint-panel" aria-label="Подсказки"><div class="hint-panel-head"><div><div class="section-label">Шесть подсказок</div><p>Каждая использованная подсказка уменьшает максимум результата на 1 балл.</p></div><span class="hint-count" id="hint-count">${hintState.remaining} осталось</span></div><div class="hint-lives" id="hint-lives" role="img" aria-label="Использовано подсказок: ${hintState.used} из 6">${Array.from({length:6},(_,i)=>`<span class="hint-life ${i<hintState.used?'spent':''}"></span>`).join('')}</div><div class="hint-list" id="hint-list">${hintState.opened.map(item=>hintCard(item,item.index)).join('')}</div><button class="secondary hint-open" id="open-hint" type="button" ${hintState.remaining<=0?'disabled':''}>${hintState.remaining>0?'Открыть подсказку':'Подсказки закончились'}</button><div class="hint-error error" id="hint-error" role="alert" hidden></div></section>
      <details class="glossary source-details"><summary>Источники по историческому событию</summary><ul class="source-list">${(r.sources||[]).map(sourceItem).join('')}${r.market_source?`<li>${esc(r.market_source_label||'Котировки MOEX')} · <a href="${esc(r.market_source)}" target="_blank" rel="noreferrer">Открыть котировки ↗</a></li>`:''}</ul></details><details class="glossary order-book-note"><summary>Данные стакана заявок</summary><p>Исторического архива книги заявок в этом наборе нет. Дневные цены закрытия не позволяют восстановить объёмы и лучшие цены покупки и продажи, поэтому стакан здесь не показывается.</p></details>
      ${r.glossary?.length?`<details class="glossary"><summary>Словарь</summary>${r.glossary.map(g=>`<div><b>${esc(g.term)}</b><span>${esc(g.simple)}</span></div>`).join('')}</details>`:''}
    </section>
    <form class="panel form-panel game-area" id="answer-form" data-area="decision" role="tabpanel" aria-label="Принять решение">
      <div class="form-section"><div class="section-label">Компания и период</div><label class="field-label">Компания<select class="field" name="company" required><option value="">Выберите компанию…</option>${companies}</select></label><div class="field-grid"><label class="field-label">Год<select class="field" name="year" required><option value="">Год…</option>${yearOptions}</select></label><label class="field-label">Месяц<select class="field" name="month" required><option value="">Месяц…</option></select></label></div></div>
      <div class="form-section"><div class="section-label">Ваш прогноз на 30 торговых дней</div><div class="choice-row">${[['up','Рост','выше порога'],['flat','Стабильность','в пределах порога'],['down','Падение','ниже порога']].map(([v,t,s])=>`<div class="choice"><input type="radio" id="f-${v}" name="forecast" value="${v}"><label for="f-${v}"><span>${t}</span><small>${s}</small></label></div>`).join('')}</div><label class="field-label">Обоснование<textarea class="textarea" name="rationale" maxlength="500" placeholder="Какой фактор может повлиять на цену и почему?"></textarea></label><label class="confidence-field">Уверенность <output id="confidence-value">3 из 5</output><input type="range" name="confidence" min="1" max="5" value="3"></label><div class="forecast-note" id="forecast-note">Выберите направление: схема появится в прогнозируемом периоде.</div></div>
      <div class="form-section"><div class="section-label">Стратегия</div><div class="choice-row strategy-row">${[['buy','Купить','вся сумма в акции'],['hold','Удерживать','поровну'],['sell','Продать','вся сумма в деньгах']].map(([v,t,s])=>`<div class="choice"><input type="radio" id="s-${v}" name="strategy" value="${v}"><label for="s-${v}"><span>${t}</span><small>${s}</small></label></div>`).join('')}</div><details class="hint-details"><summary>Правила виртуального портфеля</summary><p>Стартовый капитал — 100 000 ₽. Комиссии, налоги и дивиденды не учитываются.</p></details></div>
      <div class="form-section"><div class="section-label">Какие факторы вы считаете важными?</div>${factors}</div><div class="form-section"><div class="section-label">Проверьте понимание</div>${quiz}</div>
      <div class="submit-row"><button class="primary" type="submit" id="lock-answer" disabled>Зафиксировать решение ${icons.arrow}</button><div class="error" id="form-error" role="alert" hidden></div></div></form></div></main></div>`;
  bindNav();bindRound();
}
function resultView(result,idx){const labels={up:'Рост',flat:'Без существенного изменения',down:'Падение'},strategies={buy:'Купить',hold:'Удержать',sell:'Продать'},substanceLabels={none:'Аргументация не обнаружена',partial:'Есть мысль для проверки',substantive:'Есть экономическая аргументация'};const points=result.reveal_prices.map(p=>({value:p.close/result.reveal_prices[59].close*100,date:p.date,close:p.close})),startPrice=result.reveal_prices[59].close,endPrice=result.reveal_prices[89].close;const date=new Date(`${result.end_date}T12:00:00`),dateLabel=`${date.getDate()} ${MONTHS_GENITIVE[date.getMonth()]} ${date.getFullYear()}`,s=result.summary||{},fb=result.argument_feedback||{},parts=result.score?.components||{},partNames={historical:'Компания и период',forecast:'Точность прогноза',strategy_consistency:'Последовательность стратегии',understanding:'Понимание материала',argumentation:'Качество обоснования'},partHtml=Object.entries(partNames).map(([key,label])=>parts[key]?`<div class="score-part"><span>${label}</span><b>${parts[key].points} / ${parts[key].maximum}</b></div>`:'').join(''),review=(result.quiz_result.review||[]).map((q,i)=>`<div class="quiz-review"><span>${i+1}. ${esc(q.question)}</span><small>${q.selected_option===q.correct_option?'Верно':'Разбор'} · ${esc(q.explanation)}</small></div>`).join(''),sources=(result.sources||[]).map(x=>`<li>${esc(x)}</li>`).join(''),marketSource=result.source?`<li><a href="${esc(result.source)}" target="_blank" rel="noreferrer">${esc(result.source_label||'Котировки MOEX ISS · TQBR')} ↗</a></li>`:'';root.innerHTML=`<div class="game-shell"><header class="game-top"><div class="game-title">${brand()}</div>${progress()}<span class="game-meta">разбор раунда ${idx+1} / 5</span></header><main class="result-layout"><section class="result-banner"><div><div class="result-label">Ситуация раскрыта</div><h1>Вы анализировали акции компании «${esc(result.company_name)}»</h1><p>Дата решения: ${dateLabel}</p></div><div class="result-hero-score"><strong class="result-change ${result.change_pct>=0?'up':'down'}">${pct(result.change_pct)}<small>Изменение цены акции за следующие 30 торговых дней</small></strong><b>${result.score?.total??0} / ${result.score?.maximum??10} игровых баллов</b></div></section><div class="finance-context">Цена акции: ${Number(startPrice).toLocaleString('ru-RU')} ₽ → ${Number(endPrice).toLocaleString('ru-RU')} ₽. Изменение = (конечная цена / начальная цена − 1) × 100.</div><div class="result-grid"><section class="panel result-chart"><div class="panel-head"><div><h2>Фактическое продолжение цены</h2><div class="panel-sub">Реальные котировки за 90 торговых дней · индекс графика относительно начала</div></div></div><div class="chart-wrap">${chartSvg(points,{mode:'revealed',forecast:result.answer?.forecast})}</div><div class="chart-legend"><span><i class="legend-line actual"></i>Фактические котировки</span><span><i class="legend-line predicted"></i>Ваш прогноз</span></div><div class="stats-row"><div class="stat-card"><span>Компания</span><b class="${result.company_correct?'good':'bad'}">${result.company_correct?'угадана':'не угадана'}</b></div><div class="stat-card"><span>Период</span><b class="${result.period_correct?'good':'bad'}">${result.period_correct?'точно':dateLabel}</b></div><div class="stat-card"><span>Прогноз</span><b class="${result.forecast_correct?'good':'bad'}">${result.forecast_correct?'верный':labels[result.actual_forecast]}</b></div></div><div class="portfolio-outcome"><b>Выбранная стратегия: «${strategies[result.strategy]}»</b><span>Итоговая стоимость портфеля: ${money(result.portfolio_end)}</span><span>Изменение капитала: ${money(result.portfolio_end-100000)} (${pct(result.portfolio_change_pct)})</span></div><section class="score-breakdown"><div class="section-label">Игровые баллы</div>${partHtml}<p>Использовано подсказок: ${result.hints_used||0}. Каждая подсказка уменьшает возможный максимум на 1 балл; максимум после подсказок — ${result.score?.maximum??10} из 10. Игровые баллы не являются прибылью.</p></section></section><section class="panel result-explain"><h2>Образовательный разбор</h2><div class="lesson-block"><span>Что произошло</span><p>${esc(s.what_happened||result.lesson)}</p></div><div class="lesson-block"><span>Почему это важно</span><p>${esc(s.why_important||'')}</p></div><div class="lesson-block"><span>Что остаётся неоднозначным</span><p>${esc(s.uncertainty||'')}</p></div><div class="takeaway"><span>Главная мысль</span><b>${esc(s.key_takeaway||result.lesson)}</b></div><div class="argument-review"><div class="section-label">Ваше обоснование · ${esc(substanceLabels[fb.substance]||'разбор')}</div><p>${esc(fb.explanation||'Обоснование не оценено.')}</p>${fb.factors?.length?`<p><b>Выделенные факторы:</b> ${esc(fb.factors.join(', '))}</p>`:''}${fb.contradictions?.length?`<p><b>Что стоит уточнить:</b> ${esc(fb.contradictions.join(' · '))}</p>`:''}<p><b>Следующий шаг:</b> ${esc(fb.recommendation||'Сопоставьте несколько сигналов.')}</p><small>${fb.provider==='llm'?'Структурированный разбор LLM':'Локальная проверка · LLM недоступна'} · неопределённость: ${esc(fb.uncertainty||'высокая')}</small></div><div class="alt-title">Сравнение стратегий · портфель через 30 торговых дней</div><div class="alt-grid">${['buy','hold','sell'].map(k=>`<div class="alt ${k===result.strategy?'active':''}"><span>${strategies[k]}${k===result.strategy?' · ваш выбор':''}</span><strong>${money(result.alternatives[k])}</strong></div>`).join('')}</div><div class="quiz-score">Понимание материала: <b>${result.quiz_result.correct} / ${result.quiz_result.total}</b></div><div class="quiz-review-list">${review}</div>${sources||marketSource?`<div class="alt-title">Источники</div><ul class="source-list">${sources}${marketSource}</ul>`:""}<div class="calculation-note">${esc(result.calculation_note||"")}</div><div class="factor-feedback"><div class="section-label">Разбор выбранных факторов</div><p><b>Ваш выбор:</b> ${esc((result.factor_analysis?.selected||[]).join(", ")||"не выбраны")}</p><p><b>Другие сигналы:</b> ${esc((result.factor_analysis?.other_candidates||[]).join(", ")||"нет")}</p><p>${esc(result.factor_analysis?.interpretation||"Сопоставляйте несколько факторов и не приписывайте движению одну причину.")}</p><p><b>Каких данных не хватало:</b> ${esc(result.factor_analysis?.missing_data||"")}</p></div></section></div><div class="result-actions"><span class="round-score">Игровые баллы и виртуальный портфель показаны отдельно.</span><button class="primary" id="next-round">${idx===4?'Посмотреть итоги':'Следующий раунд'} ${icons.arrow}</button></div></main></div>`;bindNav();document.getElementById('next-round').onclick=()=>{activeResult=null;localStorage.removeItem(RESULT_KEY);render();};}
function summaryView(){const rounds=session.history;const historical=rounds.reduce((n,r)=>n+r.score.historical_accuracy,0),forecasts=rounds.reduce((n,r)=>n+r.score.forecast_accuracy,0),understanding=rounds.reduce((n,r)=>n+r.score.understanding,0);root.innerHTML=`<div class="game-shell"><header class="game-top">${brand()}<span class="nav-badge">Сессия завершена</span></header><main class="summary"><div class="summary-head"><div class="summary-icon">05</div><div class="round-kicker">ПЯТЬ РАУНДОВ ПРОЙДЕНО</div><h1>Вы собрали карту собственных решений.</h1><p>Результат — это не только точность. Смотрите, где помог анализ, а где сработала неопределённость.</p></div><div class="summary-cards"><div class="panel summary-card"><span>Историческая точность</span><b>${historical} / 10</b><small>компания и период</small></div><div class="panel summary-card"><span>Точность прогнозов</span><b>${forecasts} / 5</b><small>направление цены</small></div><div class="panel summary-card"><span>Понимание факторов</span><b>${understanding} / ${rounds.length*2}</b><small>ответы мини-тестов</small></div></div><section class="panel review-list">${rounds.map((r,i)=>`<article class="review-item"><span class="review-num">${String(i+1).padStart(2,'0')}</span><div><b>${esc(r.company_name)} · ${pct(r.change_pct)}</b><small>${r.company_correct?'компания угадана':'компания не угадана'} · ${r.forecast_correct?'прогноз верный':'прогноз мимо'} · тест ${r.quiz_result.correct}/${r.quiz_result.total}</small></div><strong>${money(r.portfolio_end)}</strong></article>`).join('')}</section><div class="summary-actions"><button class="primary" id="profile-after">Открыть профиль ${icons.arrow}</button><button class="secondary" id="play-again">Повторить ${levelMeta[session.level||level].name}</button></div></main></div>`;bindNav();document.getElementById('profile-after').onclick=profileView;document.getElementById('play-again').onclick=()=>startGame(false);}
function profilePreferencesMarkup(p){const filters=p.scenario_filters||{periods:[],geographies:[]},prefs=p.user.preferences||{period:'all',geography:'moex'};return `<section class="panel profile-section preference-panel"><div class="section-label">Предпочтения сценариев</div><p>Фильтр применяется к новым сессиям. Для каждого выбора нужны пять проверенных исторических сценариев.</p><form id="preferences-form" class="preferences-form"><label class="field-label">Период<select class="field" name="period">${filters.periods.map(x=>`<option value="${esc(x.key)}" ${prefs.period===x.key?'selected':''}>${esc(x.label)} · ${x.count} сценариев</option>`).join('')}</select></label><label class="field-label">Рынок<select class="field" name="geography">${filters.geographies.map(x=>`<option value="${esc(x.key)}" ${prefs.geography===x.key?'selected':''}>${esc(x.label)} · ${x.count} сценариев</option>`).join('')}</select></label><button class="secondary" id="save-preferences" type="submit">Сохранить предпочтения</button><span class="preference-status" id="preference-status" role="status"></span></form><small>Сейчас в каталоге доступны только MOEX и сценарии 2020-х. Другие периоды и рынки появятся после проверки данных.</small></section>`;}
async function profileView(){root.innerHTML='<div class="loading">Собираем профиль…</div>';try{const p=await api('/api/profile'),stats=p.stats,registered=new Date(p.user.created_at).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});root.innerHTML=shell(`<main class="profile"><section class="profile-head"><div><h1>Мой профиль</h1><p>${esc(p.user.display_name)} · ${esc(p.user.email)} · Официально SLAY с ${registered}</p></div></section><div class="profile-grid"><section class="panel metrics"><h2 class="card-heading">Общая статистика</h2><div class="metric-grid">${[['Завершённых сессий',stats.completed_sessions],['Пройдено раундов',stats.rounds],['Точность прогнозов',stats.forecast_accuracy===null?'—':stats.forecast_accuracy+'%'],['Историческая точность',stats.historical_accuracy+'%'],['Тесты понимания',stats.quiz_accuracy+'%'],['Средний результат',stats.average_score===null?'—':`${stats.average_score} / 10`],['Использовано подсказок',stats.hints_used],['Максимальный открытый уровень',levelMeta[p.user.unlocked_level]?.name||'Easy']].map(([a,b])=>`<div class="metric"><span>${a}</span><b>${b}</b></div>`).join('')}</div></section>${profilePreferencesMarkup(p)}<section class="panel profile-section"><h2 class="card-heading">Статистика стратегий</h2><div class="strategy-stats">${[['buy','Купили'],['hold','Удержали'],['sell','Продали']].map(([key,label])=>{const n=stats.strategies?.[key]||0;return `<div><span>${label} ${n} ${pluralTimes(n)}</span><b>${n}</b></div>`}).join('')}</div><p>Подсказок использовано в среднем: ${stats.average_hints_used===null?'—':stats.average_hints_used} за раунд.</p></section><section class="panel profile-section"><h2 class="card-heading">Сильные стороны</h2>${p.strengths.length?p.strengths.map(x=>`<div class="insight good">${esc(x)}</div>`).join(''):'<p class="empty">Данных пока недостаточно для надёжных выводов. Завершите несколько раундов.</p>'}</section><section class="panel profile-section"><h2 class="card-heading">Слабые стороны</h2>${p.weaknesses.length?p.weaknesses.map(x=>`<div class="insight"><b>${esc(x.topic)}</b><p>${esc(x.detail)}</p></div>`).join(''):'<p class="empty">Пока нет устойчивых слабых тем. Завершите ещё несколько раундов.</p>'}</section><section class="panel profile-section"><h2 class="card-heading">Рекомендации</h2>${p.recommendations.length?p.recommendations.map(x=>`<div class="insight"><b>${esc(x.topic)}</b><p>${esc(x.detail)}</p><a href="#" class="tutorial-link">Повторить вводный урок →</a></div>`).join(''):'<p class="empty">Рекомендации появятся, когда накопится достаточно ответов.</p>'}<button class="text-button" id="tutorial-replay">Повторить вводный урок</button></section><section class="panel profile-section"><h2 class="card-heading">История сессий</h2>${p.history.length?p.history.map(x=>`<div class="history-row"><span>${new Date(x.completed_at).toLocaleDateString('ru-RU')}</span><b>${levelMeta[x.level]?.name||x.level}</b><small>${x.rounds.length} раундов</small><details class="history-detail"><summary>Открыть ответы</summary>${x.rounds.map(r=>`<p><b>Раунд ${r.round_index+1}.</b> ${esc(r.result.company_name)} · прогноз: ${esc(r.forecast)} · стратегия: ${esc(r.strategy)}</p><p class="history-answer">${esc(r.rationale)}</p>`).join("")}</details></div>`).join(''):'<p class="empty">Завершённые сессии появятся здесь.</p>'}</section></div></main>`);bindNav();document.getElementById('preferences-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=document.getElementById('save-preferences'),status=document.getElementById('preference-status');button.disabled=true;status.textContent='Сохраняем…';try{const saved=await api('/api/profile/preferences',{method:'POST',body:JSON.stringify({period:form.elements.period.value,geography:form.elements.geography.value})});user=saved.user;status.textContent='Сохранено для новых сессий.';}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};const replay=async()=>{try{const result=await api('/api/tutorial/restart',{method:'POST',body:'{}'});user=result.user;tutorialView();}catch(err){errorScreen(err.message);}};document.getElementById('tutorial-replay').onclick=replay;document.querySelectorAll('.tutorial-link').forEach(a=>a.onclick=e=>{e.preventDefault();replay();});}catch(err){errorScreen(err.message);}}
function bindRound(){
  const form=document.getElementById('answer-form'),button=document.getElementById('lock-answer'),draftKey=`slay_draft_${session.session_id}_${session.round_index}`,periods=session.current.periods||[],draft=JSON.parse(localStorage.getItem(draftKey)||'{}');
  for(const [name,value] of Object.entries(draft)){[...form.elements].filter(el=>el.name===name).forEach(el=>{el.checked=Array.isArray(value)?value.includes(el.value):el.type==='radio'||el.type==='checkbox'?String(value)===el.value:false;if(!['radio','checkbox'].includes(el.type))el.value=value;});}
  const year=form.elements.year,month=form.elements.month,chart=document.getElementById('round-chart');
  const updateMonths=(keep=true)=>{const old=keep?month.value:'';const choices=periods.filter(p=>String(p[0])===year.value).map(p=>Number(p[1])).sort((a,b)=>a-b);month.innerHTML=`<option value="">Выберите месяц…</option>${choices.map(m=>`<option value="${m}">${MONTHS[m-1]}</option>`).join('')}`;if(choices.includes(Number(old)))month.value=old;};
  updateMonths(false);if(draft.month)month.value=String(draft.month);
  const saveDraft=()=>{const saved={};for(const el of form.elements){if(el.type==='checkbox'){saved[el.name]??=[];if(el.checked)saved[el.name].push(el.value);}else if(el.type==='radio'){if(el.checked)saved[el.name]=el.value;}else if(el.name)saved[el.name]=el.value;}localStorage.setItem(draftKey,JSON.stringify(saved));};
  const hintButton=document.getElementById('open-hint');
  hintButton?.addEventListener('click',async()=>{const state=session.hint_state||{used:0,remaining:6,opened:[]},box=document.getElementById('hint-error');if(state.remaining<=0)return;hintButton.disabled=true;hintButton.textContent='Открываем…';box.hidden=true;try{const opened=await api('/api/hint',{method:'POST',body:JSON.stringify({session_id:session.session_id,round_index:session.round_index,hint_index:state.used})});const next={used:opened.used,remaining:opened.remaining,opened:[...state.opened,opened.hint]};session.hint_state=next;document.getElementById('hint-count').textContent=`${next.remaining} осталось`;document.getElementById('hint-lives').innerHTML=Array.from({length:6},(_,i)=>`<span class="hint-life ${i<next.used?'spent':''}"></span>`).join('');document.getElementById('hint-lives').setAttribute('aria-label',`Использовано подсказок: ${next.used} из 6`);document.getElementById('hint-list').insertAdjacentHTML('beforeend',hintCard(opened.hint,opened.hint.index));hintButton.disabled=next.remaining<=0;hintButton.textContent=next.remaining?`Открыть подсказку · максимум ${opened.max_score} из 10`:'Подсказки закончились';}catch(error){box.textContent=error.message;box.hidden=false;hintButton.disabled=false;hintButton.textContent='Повторить открытие';}});
  const check=()=>{const d=new FormData(form),q=session.current.quiz.every(item=>d.get(`quiz-${item.id}`)!==null),validPeriod=periods.some(p=>String(p[0])===d.get('year')&&String(p[1])===d.get('month')),hasFactor=d.getAll('factor').length>0;button.disabled=!(d.get('company')&&validPeriod&&d.get('forecast')&&d.get('strategy')&&hasFactor&&q);};
  year.addEventListener('change',()=>{updateMonths(false);saveDraft();check();});
  form.addEventListener('input',()=>{saveDraft();check();});form.addEventListener('change',()=>{saveDraft();check();});
  form.querySelectorAll('input[name="forecast"]').forEach(el=>el.addEventListener('change',()=>{const selected=form.elements.forecast.value;chart.innerHTML=chartSvg(session.current.chart,{mode:'round',forecast:selected});document.getElementById('forecast-note').textContent='Пунктир показывает схему выбранной гипотезы, а не ожидаемую цену.';}));
  const confidence=form.elements.confidence;confidence.addEventListener('input',()=>{document.getElementById('confidence-value').value=`${confidence.value} из 5`;});
  document.getElementById('chart-help').addEventListener('click',e=>{const copy=document.getElementById('chart-help-copy');copy.hidden=!copy.hidden;e.currentTarget.setAttribute('aria-expanded',String(!copy.hidden));});
  let chartZoom=1;const setZoom=value=>{chartZoom=Math.max(1,Math.min(3,value));chart.style.setProperty('--chart-zoom',String(chartZoom));};document.getElementById('chart-zoom-in').addEventListener('click',()=>setZoom(chartZoom+.5));document.getElementById('chart-zoom-out').addEventListener('click',()=>setZoom(chartZoom-.5));document.getElementById('chart-zoom-reset').addEventListener('click',()=>{setZoom(1);chart.scrollTo({left:0,behavior:'smooth'});});
  const tooltip=document.getElementById('chart-tooltip'),showPoint=e=>{const svg=chart.querySelector('svg'),rect=svg?.getBoundingClientRect();if(!rect||!tooltip)return;const clientX=e.clientX??(e.touches?.[0]?.clientX);if(clientX==null)return;const ratio=Math.max(0,Math.min(1,(clientX-rect.left)/rect.width)),index=Math.round(ratio*89);if(index>=session.current.chart.length){tooltip.hidden=true;return;}const values=session.current.chart,point=values[index],base=Number(values[0].value),value=Number(point.value),previous=index?Number(values[index-1].value):value,change=(value/base-1)*100,step=index?(value/previous-1)*100:0;tooltip.textContent=`Торговый день ${index+1} · ${value.toLocaleString('ru-RU',{maximumFractionDigits:2})} · ${change>=0?'+':''}${change.toLocaleString('ru-RU',{maximumFractionDigits:2})}% к началу · ${index?'за день: '+(step>=0?'+':'')+step.toLocaleString('ru-RU',{maximumFractionDigits:2})+'%':'первое наблюдение'}`;tooltip.hidden=false;};chart.addEventListener('pointermove',showPoint);chart.addEventListener('pointerleave',()=>{tooltip.hidden=true;});chart.addEventListener('click',showPoint);chart.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const day=Number(chart.dataset.activeDay||1)+(e.key==='ArrowRight'?1:-1),index=Math.max(0,Math.min(session.current.chart.length-1,day-1));chart.dataset.activeDay=String(index+1);const p=session.current.chart[index],value=Number(p.value);tooltip.textContent=`Торговый день ${index+1} · ${value.toLocaleString('ru-RU',{maximumFractionDigits:2})}`;tooltip.hidden=false;}});
  document.querySelectorAll('.tab-button').forEach(tab=>tab.addEventListener('click',()=>{const mobile=matchMedia('(max-width: 980px)').matches;if(!mobile)return;document.querySelectorAll('.tab-button').forEach(item=>{const active=item===tab;item.classList.toggle('active',active);item.setAttribute('aria-selected',String(active));});document.querySelectorAll('.game-area').forEach(area=>area.classList.toggle('mobile-hidden',area.dataset.area!==tab.dataset.panel));}));
  if(matchMedia('(max-width: 980px)').matches){form.classList.add('mobile-hidden');document.querySelector('[data-panel="investigation"]').setAttribute('aria-selected','true');document.querySelector('[data-panel="decision"]').setAttribute('aria-selected','false');}
  check();
  form.onsubmit=async e=>{e.preventDefault();if(button.disabled)return;button.disabled=true;button.textContent='Фиксируем решение…';const d=new FormData(form),answer={session_id:session.session_id,round_index:session.round_index,company:d.get('company'),year:d.get('year'),month:d.get('month'),forecast:d.get('forecast'),confidence:Number(d.get('confidence')),strategy:d.get('strategy'),rationale:d.get('rationale'),factors:d.getAll('factor').map(Number),quiz_answers:session.current.quiz.map(q=>({id:q.id,option:Number(d.get(`quiz-${q.id}`))}))};try{const payload=await api('/api/answer',{method:'POST',body:JSON.stringify(answer)});session=payload.session;activeResult=payload.result;localStorage.removeItem(draftKey);localStorage.setItem(RESULT_KEY,JSON.stringify({session_id:session.session_id,index:session.round_index-1,result:activeResult}));render();}catch(err){const box=document.getElementById('form-error');box.textContent=err.message;box.hidden=false;button.disabled=false;button.innerHTML=`Зафиксировать решение ${icons.arrow}`;}};
}
function render(){if(activeResult)return resultView(activeResult,session.round_index-1);if(session.round_index>=5)return summaryView();roundView();}
function errorScreen(msg){root.innerHTML=shell(`<main class="error-screen"><div class="eyebrow">Системное сообщение</div><h1>Не удалось открыть рабочую область</h1><p>${esc(msg)}</p><button class="primary" id="retry">Повторить</button></main>`);bindNav();document.getElementById('retry').onclick=()=>user?dashboard():landing();}
async function boot(){try{const m=await api('/api/me');user=m.user;if(user?.tutorial_completed){level=localStorage.getItem(LEVEL_KEY(user.id))||'easy';if(localStorage.getItem(SESSION_USER_KEY)!==user.id)clearSavedSession();const saved=localStorage.getItem(SESSION_KEY);saved?startGame(true):dashboard();}else if(user){clearSavedSession();tutorialView();}else landing();}catch{landing();}}
boot();
